# Generated by test-lab — blind adversarial evaluation
"""Opt-in live E2E check for `$ask` GPT-5.5 High review-bundle routing."""

from __future__ import annotations

from dotenv import find_dotenv, load_dotenv

load_dotenv(find_dotenv(usecwd=True), override=False)

import json
import os
import subprocess
from pathlib import Path
from typing import Any

import pytest


pytestmark = pytest.mark.skipif(
    os.environ.get("ASK_LIVE_GPT55_REVIEW_BUNDLE_E2E") != "1",
    reason="set ASK_LIVE_GPT55_REVIEW_BUNDLE_E2E=1 to run the real GPT-5.5 High review-bundle E2E",
)


SENTINELS = (
    "ADD_TASK_BYPASS_SENTINEL",
    "WRONG_REPO_ROOT_SENTINEL",
    "ORCHESTRATE_REVIEW_GATE_SENTINEL",
)


def _json_from_stdout(stdout: str) -> dict[str, Any]:
    stripped = stdout.strip()
    if not stripped:
        raise AssertionError("expected JSON on stdout, got empty output")
    try:
        loaded = json.loads(stripped)
    except json.JSONDecodeError:
        first_brace = stripped.find("{")
        if first_brace < 0:
            raise
        loaded = json.loads(stripped[first_brace:])
    assert isinstance(loaded, dict)
    return loaded


def test_live_gpt55_high_review_bundle_e2e(tmp_path: Path) -> None:
    skill_dir = Path(__file__).resolve().parents[1]
    run_root = tmp_path / "runs"
    ask_id = "live-gpt55-high-review-bundle-e2e"
    bundle = tmp_path / "review-bundle.md"
    bundle.write_text(
        "\n".join(
            [
                "# Review Bundle",
                "",
                "## Finding candidate 1",
                "File: skills/plan/plan.py",
                "Evidence: add_task_to_plan() appends a task and then calls validate_structured_plan(data) directly.",
                "Sentinel: ADD_TASK_BYPASS_SENTINEL",
                "Expected risk: --add-task can bypass the stricter code-runner routing audit.",
                "",
                "## Finding candidate 2",
                "File: skills/governance/run.sh",
                "Evidence: from skills/governance, SCRIPT_DIR/../../.. resolves to the parent of the repo, not the repo root.",
                "Sentinel: WRONG_REPO_ROOT_SENTINEL",
                "Expected risk: governance artifact-root checks can over-block sibling directories and miss the intended repo-local boundary.",
                "",
                "## Finding candidate 3",
                "File: skills/orchestrate/run.sh",
                "Evidence: orchestration gates on text review output rather than requiring a fresh matching PASS artifact.",
                "Sentinel: ORCHESTRATE_REVIEW_GATE_SENTINEL",
                "Expected risk: a plan can reach dispatch without governance provenance or a review-plan PASS.",
                "",
            ]
        ),
        encoding="utf-8",
    )
    question = (
        f"Read this code-review bundle: {bundle}\n"
        "Produce a concise merge-blocking review finding list.\n"
        "This must be a single oracle review, not deep review and not parallel review.\n"
        "For each finding you identify, include its exact sentinel label, state whether it is merge-blocking, "
        "and explain why in one sentence.\n"
        f"You must include all of these sentinel labels: {', '.join(SENTINELS)}."
    )

    result = subprocess.run(
        [
            "./run.sh",
            "ask",
            question,
            "--oracle",
            "--oracle-backend",
            "subagent-runner",
            "--oracle-model",
            "gpt-5.5",
            "--oracle-reasoning",
            "high",
            "--oracle-timeout",
            "360",
            "--oracle-idle-timeout",
            "120",
            "--oracle-heartbeat-interval",
            "5",
            "--ask-id",
            ask_id,
            "--run-output-root",
            str(run_root),
            "--overwrite",
            "--json",
        ],
        cwd=skill_dir,
        env={**os.environ, "NO_COLOR": "1"},
        text=True,
        capture_output=True,
        timeout=420,
    )

    assert result.returncode == 0, result.stderr + "\n" + result.stdout
    payload = _json_from_stdout(result.stdout)
    answer = str(payload.get("answer", ""))

    oracle = payload.get("oracle")
    assert isinstance(oracle, dict)
    assert oracle.get("backend") == "subagent-runner"
    assert oracle.get("model") == "gpt-5.5"
    assert oracle.get("model_served") == "gpt-5.5"
    assert oracle.get("reasoning_effort") == "high"
    for sentinel in SENTINELS:
        assert sentinel in answer

    run_dir = run_root / ask_id
    status = json.loads((run_dir / f"{ask_id}.status.json").read_text(encoding="utf-8"))
    request = json.loads((run_dir / f"{ask_id}.request.json").read_text(encoding="utf-8"))
    events_text = (run_dir / f"{ask_id}.events.jsonl").read_text(encoding="utf-8")
    event_kinds = [
        event.get("kind") or event.get("event")
        for event in (json.loads(line) for line in events_text.splitlines() if line.strip())
    ]

    assert status["state"] == "answered"
    assert status["result_summary"]["oracle_enabled"] is True
    assert status["result_summary"]["oracle_model"] == "gpt-5.5"
    assert status["result_summary"]["oracle_model_served"] == "gpt-5.5"
    assert status["result_summary"]["deep_review_enabled"] is False
    assert request["oracle_backend"] == "subagent-runner"
    assert request["oracle_model"] == "gpt-5.5"
    assert request["oracle_reasoning"] == "high"
    assert request["deep_review"] is False
    assert request["parallel_review"] is False
    assert "subagent_transcript_delta" in event_kinds
    assert "subagent_session_completed" in event_kinds
    assert "--output-last-message" not in events_text
